    {
        // Each subsequent char must be lowercase letter
        assert(input[name_end].is_ascii_lowercase());
        name_end += 1;
    }
    
    // name_end should be at space
    assert(input[name_end] == ' ');

    // 3) after the space, the next word should be "Contest"
    let contest_word = ['C', 'o', 'n', 't', 'e', 's', 't'];
